//! Auto-generated wgpu bindings for `resample.wgsl`.
//!
//! A thin `include!` bridge: `wgsl_bindgen` generates the Rust source at
//! build time into `OUT_DIR/resample_generated.rs`. Nothing here is edited by
//! hand; the generated content is the source of truth for the resample
//! bind-group layout.
//!
//! The generated module `resample` exposes:
//! - `ResampleUniforms` — a `Pod + Zeroable` uniform struct (64 bytes).
//! - `WgpuBindGroup0` / `WgpuBindGroup0Entries` — typed bind-group helpers.
//!
//! The `const` assertions in `pipeline.rs` pin the uniform layout.

// JUSTIFICATION: all lints below apply to code generated by wgsl_bindgen 0.23.
// Names, derives, and patterns are controlled by the codegen tool, not by this
// crate.  Suppressing them here keeps the diagnostic surface clean without
// requiring changes to the generated content.
//
// - missing_docs / missing_debug_implementations: generated pub items lack docs
// - unsafe_code: bytemuck_impls emits `unsafe impl Pod + Zeroable`
// - unused / dead_code: wgsl_bindgen generates more items than this crate uses
// - non_snake_case / non_camel_case_types / non_upper_case_globals:
//   generated identifiers follow WGSL naming conventions, not Rust conventions
// - elided_lifetimes_in_paths: from_bindings(…) elides lifetime
// - unused_doc_comments: #[doc = "..."] on const exprs inside a const block
// - rust_2018_idioms: implied -W flag that fires on elided lifetimes
#[allow(
    missing_docs,
    missing_debug_implementations,
    unsafe_code,
    unused,
    dead_code,
    non_snake_case,
    non_camel_case_types,
    non_upper_case_globals,
    elided_lifetimes_in_paths,
    unused_doc_comments,
    unreachable_pub,
    clippy::all,
    clippy::pedantic
)]
#[expect(
    clippy::undocumented_unsafe_blocks,
    reason = "wgsl_bindgen writes `unsafe impl bytemuck::Pod`/`Zeroable` for each uniform struct into OUT_DIR, where no SAFETY comment can live; its generated const asserts pin every field offset, the alignment and the size to the WGSL layout"
)]
pub(super) mod resample_gen {
    include!(concat!(env!("OUT_DIR"), "/resample_generated.rs"));
}

/// Re-export the generated `resample` submodule at the path callers use.
pub(super) use resample_gen::resample;
